const fs = require('fs');
const path = require('path');
const {{ chromium }} = require('{PLAYWRIGHT_PATH}');
const base = '{BASE_URL}';
const runDir = {json.dumps(str(run_dir))};
const workspaceDir = {json.dumps(str(WORKSPACE))};
const shots = path.join(runDir, 'screenshots');
