  const context = await browser.newContext({{ viewport: {{ width: 1280, height: 1800 }} }});
  const page = await context.newPage();
  const phoneRegex = /(?:\\+?1[-.\\s]?)?(?:\\(?\\d{{3}}\\)?[-.\\s]?\\d{{3}}[-.\\s]?\\d{{4}})/g;
  let found = null;
  try {{
    log('TASK: Retrieve the customer service phone number from the shopping site.');
    await page.goto(base + '/', {{ waitUntil: 'domcontentloaded' }});
    await page.waitForTimeout(1500);
    log('CP1: Opened homepage ' + page.url() + ' title=' + await page.title());
    await page.screenshot({{ path: path.join(shots, 'final_execution_1_homepage.png') }});

    const footerLink = page.locator('footer').getByRole('link', {{ name: 'Contact Us' }}).first();
    await footerLink.scrollIntoViewIfNeeded();
    await footerLink.click();
    await page.waitForLoadState('domcontentloaded');
    await page.waitForTimeout(1500);
