    const bodyText = (await page.locator('body').innerText()).replace(/\\s+/g, ' ');
    const matches = bodyText.match(phoneRegex);
    if (matches && matches.length) {{
      found = matches[0];
      log('CP3: Customer service phone number displayed on page: ' + found);
    }} else {{
      log('CP3: No customer service phone number was displayed on the Contact Us page.');
    }}
    await page.screenshot({{ path: path.join(shots, 'final_execution_3_contact_text_evidence.png') }});

    const response = found
      ? {{ task_type: 'RETRIEVE', status: 'SUCCESS', retrieved_data: null, error_details: null }}
      : {{ task_type: 'RETRIEVE', status: 'NOT_FOUND_ERROR', retrieved_data: null, error_details: null }};

    if (found) {{
      log('CP4: Extracted customer service phone number: ' + found);
      log('FINAL_RESPONSE: Customer service phone number is ' + found);
    }} else {{
      log('CP4: No customer service phone number could be extracted from the reachable visible pages.');
      log('FINAL_RESPONSE: Customer service phone number not found on the site.');
    }}

    fs.writeFileSync(path.join(runDir, 'agent_response.json'), JSON.stringify(response, null, 2));
