  }} catch (e) {{
    log('ERROR: ' + String(e && e.stack || e));
    const response = {{ task_type: 'RETRIEVE', status: 'NOT_FOUND_ERROR', retrieved_data: null, error_details: null }};
    fs.writeFileSync(path.join(runDir, 'agent_response.json'), JSON.stringify(response, null, 2));
    fs.writeFileSync(path.join(workspaceDir, 'agent_response.json'), JSON.stringify(response, null, 2));
    try {{ await page.screenshot({{ path: path.join(shots, 'final_execution_error_state.png') }}); }} catch (_) {{}}
    await browser.close();
    process.exit(1);
  }}
  await browser.close();
}})();
"""
